const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const dateStr = sevenDaysAgo.toISOString().split('T')[0];
const today = now.toISOString().split('T')[0];
return [{ json: { searchDate: dateStr, todayDate: today, searchQuery: `topic:ai OR topic:llm OR topic:claude OR topic:openai OR topic:gpt OR topic:gemini stars:>50 created:>${dateStr}`, reportDate: now.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Tokyo' }) } }];

const items = $input.all();
const repos = items[0].json.items || [];
const reportDate = $('検索パラメータ設定').first().json.reportDate;
if (repos.length === 0) return [{ json: { skip: true, reason: 'No repos found' } }];
const top5 = repos.slice(0, 5);
return top5.map((repo, index) => ({ json: { rank: index + 1, name: repo.full_name, description: repo.description || '説明なし', stars: repo.stargazers_count, language: repo.language || '不明', url: repo.html_url, topics: (repo.topics || []).join(', '), created_at: repo.created_at, updated_at: repo.updated_at, forks: repo.forks_count, open_issues: repo.open_issues_count, reportDate } }));

const GITHUB_TOKEN = $env.GITHUB_TOKEN || '';
const BASE = 'https://api.github.com/repos/liquitex-coder/ai-solution-/contents/n8n/prompts/';
const headers = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'n8n-ai-navi/1.0' };
if (GITHUB_TOKEN) headers['Authorization'] = `token ${GITHUB_TOKEN}`;
async function fetchPrompt(file) {
  try {
    const res = await fetch(BASE + file, { headers });
    if (!res.ok) return '';
    const data = await res.json();
    return Buffer.from((data.content || '').replace(/\n/g, ''), 'base64').toString('utf8');
  } catch(e) { return ''; }
}
const [copyright, wfPrompt] = await Promise.all([
  fetchPrompt('00-copyright-transform.md'),
  fetchPrompt('01-github-trending.md')
]);
return [{ json: { ...$json, promptContent: copyright + '\n\n---\n\n' + wfPrompt } }];

const claudeJson = $json.content[0].text;
const currentItem = $('上位5件を整形').item.json;
const rank = currentItem.rank || 1;
const repoName = currentItem.name || '';
const shortName = repoName.split('/').pop();
const title = `【AIツール】${shortName} - 注目のAIリポジトリ第${rank}位 | GitHubトレンド`;
return [{ json: { title, content: claudeJson, wp_status: 'draft', source_url: currentItem.url || '' } }];

// Auditor Gate — graceful degrade (INV-R2: LLM-free verdict)
const auditorUrl = $env.CLAIM_AUDITOR_URL || '';
const content = $json.content || '';
const sourceUrl = $json.source_url || '';
if (!auditorUrl) {
  return [{ json: { ...$json, verdict: 'SKIP', wp_status: 'draft',
    audit_note: 'CLAIM_AUDITOR_URL未設定 → 下書き保存' } }];
}
try {
  const res = await fetch(`${auditorUrl}/audit`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      content,
      source_urls: sourceUrl ? [sourceUrl] : [],
      skill_ref: '01-github-trending'
    })
  });
  if (!res.ok) {
    return [{ json: { ...$json, verdict: 'UNVERIFIABLE', wp_status: 'draft',
      audit_note: `Auditor HTTP ${res.status}` } }];
  }
  const result = await res.json();
  return [{ json: { ...$json, ...result,
    wp_status: result.verdict === 'PASS' ? 'publish' : 'draft' } }];
} catch(e) {
  return [{ json: { ...$json, verdict: 'UNVERIFIABLE', wp_status: 'draft',
    audit_note: e.message } }];
}
